package com.example.discussions.controller;
import com.example.discussions.dto.Requests.*;import com.example.discussions.dto.Responses.Auth;import com.example.discussions.exception.ApiException;import com.example.discussions.model.User;import com.example.discussions.repository.UserRepository;import com.example.discussions.security.JwtService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}@PostMapping("/register")@ResponseStatus(HttpStatus.CREATED)public Auth register(@Valid @RequestBody Register r){if(users.existsByUsernameIgnoreCaseOrEmailIgnoreCase(r.username(),r.email()))throw new ApiException(HttpStatus.CONFLICT,"Логин или email уже используется");var u=new User();u.username=r.username();u.email=r.email();u.displayName=r.displayName();u.passwordHash=encoder.encode(r.password());users.save(u);return new Auth(jwt.create(u.username),u);}@PostMapping("/login")public Auth login(@Valid @RequestBody Login r){var u=users.findByUsernameIgnoreCase(r.username()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Неверный логин или пароль"));if(!encoder.matches(r.password(),u.passwordHash))throw new ApiException(HttpStatus.UNAUTHORIZED,"Неверный логин или пароль");return new Auth(jwt.create(u.username),u);}}
